// src/App.js
import React, { useEffect, useState } from "react";
import {
  fetchLoggedUser,
  fetchUserRepos,
  fetchCommits,
  uploadFile,
  fetchPRHeatmap,
  fetchMergeHeatmap
} from "./api/githubApi";
import "./App.css";

import { fetchTimeline } from "./api/jiraApi";

import MonthYearPicker from "./components/MonthYearPicker";
import TimelineViewer from "./components/TimelineViewer";

function App() {
  // GitHub state
  const [owner, setOwner] = useState("");
  const [repos, setRepos] = useState([]);
  const [selectedRepo, setSelectedRepo] = useState("");

  // heatmaps
  const [commitHeatmap, setCommitHeatmap] = useState({});
  const [prHeatmap, setPrHeatmap] = useState({});
  const [mergeHeatmap, setMergeHeatmap] = useState({});

  // timeline
  const [jiraKey, setJiraKey] = useState("");
  const [timeline, setTimeline] = useState(null);
  const [loadingTimeline, setLoadingTimeline] = useState(false);

  // UI
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [userCreatedAt, setUserCreatedAt] = useState(null);
  const [selectedFile, setSelectedFile] = useState(null);
  const [uploadMessage, setUploadMessage] = useState("Upload via dashboard");
  const [actionType, setActionType] = useState("commits");
  const [darkMode, setDarkMode] = useState(true);

  // apply full-screen dark mode
  useEffect(() => {
    document.body.style.margin = "0";
    document.body.style.padding = "0";
    document.body.style.backgroundColor = darkMode ? "#020617" : "#F8FAFC";
    document.body.style.color = darkMode ? "#E5E7EB" : "#020617";
  }, [darkMode]);

  // token & load user/repos
  useEffect(() => {
    const token = new URLSearchParams(window.location.search).get("token");
    if (token) {
      localStorage.setItem("token", token);
      window.history.replaceState({}, document.title, "/");
    }
  }, []);

  useEffect(() => {
    if (!localStorage.getItem("token")) return;
    fetchLoggedUser().then(res => {
      setOwner(res.data.login);
      setUserCreatedAt(res.data.created_at);
    }).catch(() => {});
    fetchUserRepos().then(res => {
      setRepos(res.data);
      if (res.data.length > 0) setSelectedRepo(res.data[0].name);
    }).catch(() => {});
  }, []);

  // build commit heatmap
  const buildCommitHeatmap = async (payload) => {
    const commitRes = await fetchCommits(payload);
    const map = {};
    const list = [];
    commitRes.data.forEach(commit => {
      const date = commit.commit.committer.date.substring(0, 10);
      map[date] = (map[date] || 0) + 1;
      list.push({
        message: commit.commit.message,
        author: commit.commit.author?.name || commit.commit.committer?.name,
        time: commit.commit.author?.date || commit.commit.committer?.date,
        url: commit.html_url
      });
    });
    setCommitHeatmap(map);
  };

  const buildPRHeatmap = async (payload) => {
    const res = await fetchPRHeatmap(payload);
    setPrHeatmap(res.data || {});
  };

  const buildMergeHeatmap = async (payload) => {
    const res = await fetchMergeHeatmap(payload);
    setMergeHeatmap(res.data || {});
  };

  const fetchData = async () => {
    if (!owner || !selectedRepo) return alert("Missing owner or repo");
    const payload = { owner, repo: selectedRepo, startDate, endDate };
    if (actionType === "commits") await buildCommitHeatmap(payload);
    if (actionType === "prs") await buildPRHeatmap(payload);
    if (actionType === "merge") await buildMergeHeatmap(payload);
    if (actionType === "clone") window.open(`https://github.com/${owner}/${selectedRepo}.git`, "_blank");
  };

  const handleUpload = async () => {
    if (!selectedFile) return alert("Select file");
    const reader = new FileReader();
    reader.onload = async () => {
      await uploadFile({
        owner,
        repo: selectedRepo,
        path: "uploads/" + selectedFile.name,
        content: reader.result.split(",")[1],
        message: uploadMessage
      });
      alert("✅ Uploaded");
      fetchData();
    };
    reader.readAsDataURL(selectedFile);
  };

  // timeline loader
  const loadTimeline = async () => {
    if (!jiraKey) return alert("Enter Jira Key");
    setLoadingTimeline(true);
    try {
      const res = await fetchTimeline({ key: jiraKey });
      setTimeline(res.data);
    } catch (e) {
      console.error(e);
      alert("Failed to load timeline from backend");
    } finally {
      setLoadingTimeline(false);
    }
  };

  // heatmap render helper (simple square grid)
  const renderHeatmap = (data) => {
    const days = Object.keys(data).sort();
    return (
      <div>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(53, 12px)", gap: 6, justifyContent: "center" }}>
          {days.map(d => {
            const level = Math.min(4, data[d] || 0);
            const colors = ["#e5e7eb", "#bbf7d0", "#4ade80", "#16a34a", "#166534"];
            return <div key={d} title={`${d}: ${data[d]}`} style={{ width: 12, height: 12, background: colors[level], borderRadius: 3 }} />;
          })}
        </div>
      </div>
    );
  };

  return (
    <div style={styles.container}>
      <div style={styles.topBar}>
        <h2>🚀 GitHub Analytics</h2>
        <div style={{ display: "flex", gap: 8 }}>
          <button onClick={() => setDarkMode(!darkMode)}>{darkMode ? "☀ Light" : "🌙 Dark"}</button>
          <button onClick={() => window.open(`https://github.com/${owner}/${selectedRepo}.git`)}>⬇ Clone</button>
        </div>
      </div>

      {!owner && (
        <button onClick={() => window.location.href = "http://localhost:8080/auth/github"}>Login with GitHub</button>
      )}

      {owner && (
        <>
          <div style={styles.form}>
            <select value={selectedRepo} onChange={e => setSelectedRepo(e.target.value)}>
              {repos.map(r => <option key={r.id} value={r.name}>{r.name}</option>)}
            </select>

            <MonthYearPicker userCreatedAt={userCreatedAt} onChange={({ startDate, endDate }) => { setStartDate(startDate); setEndDate(endDate); }} />

            <select value={actionType} onChange={e => setActionType(e.target.value)}>
              <option value="commits">Commits</option>
              <option value="prs">Pull Requests</option>
              <option value="merge">Merged PRs</option>
              <option value="clone">Clone Repo</option>
            </select>

            <button onClick={fetchData}>Analyze</button>
          </div>

          {/* heatmap */}
          <div style={styles.heatmapBox}>
            <div style={{ position: "absolute", right: 12, top: 12 }}>
              <input type="file" onChange={e => setSelectedFile(e.target.files[0])} />
              <button onClick={handleUpload} style={{ marginLeft: 8 }}>Upload</button>
            </div>

            <h3>Heatmap</h3>
            {actionType === "commits" && renderHeatmap(commitHeatmap)}
            {actionType === "prs" && renderHeatmap(prHeatmap)}
            {actionType === "merge" && renderHeatmap(mergeHeatmap)}
          </div>

          {/* timeline controls */}
          <div style={styles.timelineForm}>
            <input value={jiraKey} onChange={e => setJiraKey(e.target.value)} placeholder="Enter Jira Key (SAM-23)" />
            <button onClick={loadTimeline}>{loadingTimeline ? "Loading..." : "Load Timeline"}</button>
          </div>

          {/* timeline viewer */}
          {timeline && <TimelineViewer timeline={timeline} />}

        </>
      )}
    </div>
  );
}

const styles = {
  container: { minHeight: "100vh", padding: 20, fontFamily: "Inter, Arial, sans-serif" },
  topBar: { display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 },
  form: { display: "flex", gap: 10, justifyContent: "center", marginTop: 20 },
  heatmapBox: { width: "80%", margin: "20px auto", padding: 20, borderRadius: 12, position: "relative", background: "rgba(255,255,255,0.03)" },
  timelineForm: { display: "flex", gap: 8, justifyContent: "center", marginTop: 18 },
};

export default App;
